#include <vector>
#include <algorithm>

class Solution {
public:
    int maxArea(int h, int w, std::vector<int>& horizontalCuts, std::vector<int>& verticalCuts) {
        std::sort(horizontalCuts.begin(), horizontalCuts.end());
        std::sort(verticalCuts.begin(), verticalCuts.end());
        long long maxDh = horizontalCuts[0];
        for (int i = 1; i < (int)horizontalCuts.size(); ++i) {
            maxDh = std::max(maxDh, (long long)horizontalCuts[i] - horizontalCuts[i - 1]);
        }
        maxDh = std::max(maxDh, (long long)h - horizontalCuts.back());
        long long maxDw = verticalCuts[0];
        for (int i = 1; i < (int)verticalCuts.size(); ++i) {
            maxDw = std::max(maxDw, (long long)verticalCuts[i] - verticalCuts[i - 1]);
        }
        maxDw = std::max(maxDw, (long long)w - verticalCuts.back());
        return (maxDh * maxDw) % 1000000007;
    }
};

