class Solution {
    public int maxArea(int h, int w, int[] horizontalCuts, int[] verticalCuts) {
        Arrays.sort(horizontalCuts);
        Arrays.sort(verticalCuts);
        long maxDh = horizontalCuts[0];
        for (int i = 1; i < horizontalCuts.length; i++) {
            maxDh = Math.max(maxDh, (long)horizontalCuts[i] - horizontalCuts[i - 1]);
        }
        maxDh = Math.max(maxDh, (long)h - horizontalCuts[horizontalCuts.length - 1]);
        long maxDw = verticalCuts[0];
        for (int i = 1; i < verticalCuts.length; i++) {
            maxDw = Math.max(maxDw, (long)verticalCuts[i] - verticalCuts[i - 1]);
        }
        maxDw = Math.max(maxDw, (long)w - verticalCuts[verticalCuts.length - 1]);
        return (int)((maxDh * maxDw) % 1000000007L);
    }
}

var maxArea = function(h, w, horizontalCuts, verticalCuts) {
    horizontalCuts.sort((a, b) => a - b);
    verticalCuts.sort((a, b) => a - b);
    let maxDh = BigInt(horizontalCuts[0]);
    for (let i = 1; i < horizontalCuts.length; i++) {
        const gap = BigInt(horizontalCuts[i] - horizontalCuts[i - 1]);
        if (gap > maxDh) maxDh = gap;
    }
    const lastH = BigInt(h - horizontalCuts[horizontalCuts.length - 1]);
    if (lastH > maxDh) maxDh = lastH;
    let maxDw = BigInt(verticalCuts[0]);
    for (let i = 1; i < verticalCuts.length; i++) {
        const gap = BigInt(verticalCuts[i] - verticalCuts[i - 1]);
        if (gap > maxDw) maxDw = gap;
    }
    const lastW = BigInt(w - verticalCuts[verticalCuts.length - 1]);
    if (lastW > maxDw) maxDw = lastW;
    return Number((maxDh * maxDw) % 1000000007n);
};
